  /** 令牌刷新计划（计划任务：每 N 天自动全量刷新一次） */
  refreshPlan: () => get<RefreshPlan>('/api/accounts/refresh-plan'),
  saveRefreshPlan: (enabled: boolean, intervalDays: number, hour: number) =>
